"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8542],{78542:a=>{a.exports=JSON.parse('{"slug":"samolet-tekhdefolt-reyting-gendirektor","locale":"ko","title":"건설사 사몰레트는 한 달 사이 채권 상환 지연, 신용등급 2차례 강등, 최고경영자 사임을 겪었습니다","description":"사몰레트가 기술적 채무불이행을 일으킨 뒤 신용평가사 2곳이 등급을 BBB로 낮췄고 EU 제재 이후 최고경영자가 떠납니다. 주택 구매자와 투자자에게 어떤 의미인지 살펴봅니다.","blocks":[{"id":"b001","kind":"paragraph","text":"2026년 구월 말 사몰레트 그룹은 2,5십억 루블 규모 채권의 만기 상환을 하루 늦췄으며 송금 처리 지연 때문이라고 설명했습니다. 회사에 돈은 있지만 지급이 제때 도착하지 않은 이런 상황을 기술적 채무불이행이라고 합니다. 이후 ACRA는 사몰레트의 신용등급을 BBB로 낮추고 부정적 전망을 부여했습니다. 시월 15일 NKR도 A에서 같은 등급으로 낮췄습니다."},{"id":"b002","kind":"paragraph","text":"신용등급은 기업이 빚을 갚을 가능성을 나타냅니다. 개인의 신용이력처럼 나쁠수록 신규 대출금리가 높아집니다. NKR는 부채부담 증가, 채무상환 지표 약화, 수익성 하락을 강등 이유로 들었습니다. 부정적 전망은 주택대출 조건 강화와 연결했습니다. 주택대출이 비싸지면 아파트 판매가 줄어 건설사의 채무상환이 더 어려워지기 때문입니다."},{"id":"b003","kind":"paragraph","text":"시월 중순 EU는 사몰레트와 최고경영자 안나 아킨시나를 제재했습니다. EU는 블라디보스토크 건설현장의 북한 노동자를 이유로 들며 이를 2017년 유엔 제재 위반으로 봤습니다. 시월 16일 회사는 아킨시나가 개인 사정으로 사임한다고 발표했습니다. 후임으로 사몰레트 셀렉트 부문을 맡고 있는 이반 이바노프를 제안할 예정입니다. 이사 2명도 사임했으며 이름은 공개하지 않았습니다."},{"id":"b004","kind":"paragraph","text":"주요 채권자는 스베르방크로 사몰레트에 대한 대출은 274,2십억 루블입니다. 알렉산드르 베댜힌 이사회 수석부의장은 모든 채권자와 협력해 상황 개선안을 마련하고 있다고 밝혔습니다. 시월 9일 건설부는 건설사\xb7은행\xb7세무당국을 소집하고 대형 건설사가 모든 주택을 완공하도록 은행들에 자원 동원을 요구했습니다. 부처 발표에는 회사명이 나오지 않았습니다."},{"id":"b005","kind":"paragraph","text":"문제는 시월에 시작된 것이 아닙니다. 2026년 초 사몰레트는 정부에 48–50십억 루블의 우대대출을 요청했으나 재무부 소위원회는 중대한 문제가 없다고 판단했습니다. IPO에서 950루블에 팔렸던 주식은 칠월 배당 포기 이후 300루블 아래로 떨어졌고 시월 16일에는 약 247,6루블로 거의 4분의 일이 됐습니다. 사몰레트만의 문제도 아닙니다. 엑스페르트 RA에 따르면 2026년 9개월간 높은 등급의 실물부문 기업에 대한 평가조치 중 강등 비중은 8,1%로 2025년 전체의 1,8%보다 높았습니다."},{"id":"b006","kind":"paragraph","text":"주택 구매자에게 가장 중요한 것은 완공 여부입니다. 건설부가 은행에 요구하는 것도 완공이며 최대 채권자도 개선안을 준비하므로 현재 당국과 은행의 입장은 완공을 지지합니다. 채권 보유자에게 등급 강등은 위험이 커져 시장이 더 높은 이자를 요구한다는 뜻입니다. 계속 보유하면 스베르방크 계획에 기대는 것이고 지금 팔면 하락한 가격으로 손실을 확정하는 것입니다. 계획의 내용과 다음 지급기일까지 실행될지는 아직 모릅니다."},{"id":"b007","kind":"heading","text":"건설사 사몰레트에 무슨 일이 생겼나요?"},{"id":"b008","kind":"paragraph","text":"2026년 구월 말 회사가 2,5십억 루블의 채권 상환을 하루 늦췄습니다. 이후 ACRA와 NKR는 등급을 BBB와 부정적 전망으로 낮췄고, EU는 회사와 최고경영자를 제재했으며 안나 아킨시나는 사임을 발표했습니다."},{"id":"b009","kind":"heading","text":"기술적 채무불이행이란 무엇인가요?"},{"id":"b010","kind":"paragraph","text":"회사에 돈은 있지만 지급이 제때 도착하지 않아 채무상환이 며칠 늦어지는 것입니다. 사몰레트의 지연은 하루였으며 회사는 송금 지연을 이유로 들었습니다. 시장에는 그래도 지급자금이 빠듯하다는 신호입니다."},{"id":"b011","kind":"heading","text":"사몰레트가 짓는 주택은 어떻게 되나요?"},{"id":"b012","kind":"paragraph","text":"시월 9일 건설부는 건설사들이 주택을 완공하고 구매자에 대한 의무를 이행하도록 은행에 자원 동원을 요구했습니다. 최대 채권자인 스베르방크가 상황 개선안을 마련하고 있지만 구체적인 내용은 아직 발표하지 않았습니다."}],"sources":[{"label":"시월 12일부터 16일까지 러시아 채권시장에서 발생한 채무불이행 건수","url":"https://frankmedia.ru/310263"},{"label":"개발업체 사몰레트가 최고경영자 교체를 발표했습니다","url":"https://frankmedia.ru/310548"},{"label":"NKR가 ACRA에 이어 사몰레트 신용등급을 BBB로 낮췄습니다","url":"https://frankmedia.ru/310395"},{"label":"제재 대상이 된 러시아 건설사가 최고경영자 교체를 발표했습니다","url":"https://lenta.ru/news/2026/10/16/popavvshiy-pod-sanktsii-rossiyskiy-zastroyschik-ob-yavil-o-smene-gendirektora"},{"label":"당국이 러시아 은행들에 건설사 지원을 위한 자원 동원을 요구했습니다","url":"https://lenta.ru/news/2026/10/09/mobilizovat"}],"sourceBodySha256":"556c692bc853437d88a15a7dc68acf4d7948a9d61dd5f274aba150be3640471e"}')}}]);